TYPE.TEST:


SetFunctionName("Soa4MaskScalar()");

Soa4MaskScalar v;
Validate( true ); // Take address of v so that it is referenced



SetFunctionName("Soa4MaskScalar(const Soa4MaskScalar&)");

Soa4MaskScalar ref(CreateSoa4MaskScalar(true, false, false, true));

Validate( IsEqual(ref, CreateSoa4MaskScalar(true, false, false, true)) );



SetFunctionName("Soa4MaskScalar(VectorIntrinsicInParam)");

Soa4MaskScalar ref;
::rw::math::vpu::detail::VectorIntrinsicUnion vu;
vu.scalarUInt[0] = 1;
vu.scalarUInt[1] = 2;
vu.scalarUInt[2] = 3;
vu.scalarUInt[3] = 4;
ref.mV = vu.vector;
Soa4MaskScalar r(vu.vector);


Validate( IsEqual(r, ref) );



SetFunctionName("Soa4MaskScalarFromBool(bool)");

Soa4MaskScalar ref1(CreateSoa4MaskScalar(true, true, true, true));
Soa4MaskScalar r1(Soa4MaskScalarFromBool(true));

Soa4MaskScalar ref2(CreateSoa4MaskScalar(false, false, false, false));
Soa4MaskScalar r2(Soa4MaskScalarFromBool(false));

Validate( IsEqual(r1, ref1) &&
          IsEqual(r2, ref2)
);



SetFunctionName("Soa4MaskScalarFromUInt(uint32_t v)");

Soa4MaskScalar ref(CreateSoa4MaskScalarFromUInt(0x12345678U, 0x12345678U, 0x12345678U, 0x12345678U));
Soa4MaskScalar r(Soa4MaskScalarFromUInt(0x12345678U));

Validate( IsEqual(r, ref) );



SetFunctionName("Soa4MaskScalar(vpu::Soa4MaskScalar &)");

Soa4MaskScalar ref(CreateSoa4MaskScalar(true, true, true, true));
Soa4MaskScalar r(Soa4MaskScalarFromBool(true));


Validate( IsEqual(r, ref) );



SetFunctionName("Soa4MaskScalar(bool, bool, bool, bool)");

Soa4MaskScalar ref(CreateSoa4MaskScalar(true, false, true, true));
Soa4MaskScalar r(Soa4MaskScalarFromBools(true, false, true, true));


Validate( IsEqual(r, ref) );



SetFunctionName("operator =(const Soa4MaskScalar&)");

Soa4MaskScalar ref(Soa4MaskScalarFromBool(true));
Soa4MaskScalar r;
r = ref;

Validate( IsEqual(r, ref) );



SetFunctionName("Soa4MaskScalarFromBools(bool, bool, bool, bool)");

Soa4MaskScalar ref(CreateSoa4MaskScalar(false, true, true, false));
Soa4MaskScalar r(Soa4MaskScalarFromBools(false, true, true, false));


Validate( IsEqual(r, ref) );



SetFunctionName("Soa4MaskScalarFromUInts(uint32_t, uint32_t, uint32_t, uint32_t)");

Soa4MaskScalar ref( CreateSoa4MaskScalarFromUInt(0x23425U, 0x36127U, 0x6825U, 0x5236U));
Soa4MaskScalar r(Soa4MaskScalarFromUInts(0x23425U, 0x36127U, 0x6825U, 0x5236U));

Validate( IsEqual(r, ref) );



SetFunctionName("Soa4MaskScalarFromMaskScalars(vpu::MaskScalar::InParam, vpu::MaskScalar::InParam, vpu::MaskScalar::InParam, vpu::MaskScalar::InParam)");

Soa4MaskScalar ref(CreateSoa4MaskScalar(true, false, true, false));
Soa4MaskScalar r(Soa4MaskScalarFromMaskScalars(MaskScalar(true), MaskScalar(false), MaskScalar(true), MaskScalar(false)));

Validate( IsEqual(r, ref) );



SetFunctionName("IsAnyTrue(Soa4MaskScalar)");

Soa4MaskScalar testA(Soa4MaskScalarFromBools(false, true, true, false));
Soa4MaskScalar testB(Soa4MaskScalarFromBools(false, true, false, false));
Soa4MaskScalar testC(Soa4MaskScalarFromBools(true, true, true, true));
Soa4MaskScalar testD(Soa4MaskScalarFromBools(false, false, false, false));

Validate(
     IsAnyTrue(testA) &&
     IsAnyTrue(testB) &&
     IsAnyTrue(testC) &&
    !IsAnyTrue(testD)
);



SetFunctionName("IsAllTrue(Soa4MaskScalar)");

Soa4MaskScalar testA(Soa4MaskScalarFromBools(false, true, true, false));
Soa4MaskScalar testB(Soa4MaskScalarFromBools(false, true, false, false));
Soa4MaskScalar testC(Soa4MaskScalarFromBools(true, true, true, true));
Soa4MaskScalar testD(Soa4MaskScalarFromBools(false, false, false, false));

Validate(
    !IsAllTrue(testA) &&
    !IsAllTrue(testB) &&
     IsAllTrue(testC) &&
    !IsAllTrue(testD)
);



SetFunctionName("IsAnyFalse(Soa4MaskScalar)");

Soa4MaskScalar testA(Soa4MaskScalarFromBools(false, true, true, false));
Soa4MaskScalar testB(Soa4MaskScalarFromBools(false, true, false, false));
Soa4MaskScalar testC(Soa4MaskScalarFromBools(true, true, true, true));
Soa4MaskScalar testD(Soa4MaskScalarFromBools(false, false, false, false));

Validate(
     IsAnyFalse(testA) &&
     IsAnyFalse(testB) &&
    !IsAnyFalse(testC) &&
     IsAnyFalse(testD)
);



SetFunctionName("IsAllFalse(Soa4MaskScalar)");

Soa4MaskScalar testA(Soa4MaskScalarFromBools(false, true, true, false));
Soa4MaskScalar testB(Soa4MaskScalarFromBools(false, true, false, false));
Soa4MaskScalar testC(Soa4MaskScalarFromBools(true, true, true, true));
Soa4MaskScalar testD(Soa4MaskScalarFromBools(false, false, false, false));

Validate(
    !IsAllFalse(testA) &&
    !IsAllFalse(testB) &&
    !IsAllFalse(testC) &&
     IsAllFalse(testD)
);



SetFunctionName("Not(Soa4MaskScalar)");

Soa4MaskScalar result(Not(Soa4MaskScalarFromBools(true, false, false, true)));
Soa4MaskScalar ref(Soa4MaskScalarFromBools(false, true, true, false));

Validate( IsEqual(result, ref) );



SetFunctionName("And(Soa4MaskScalar)");

Soa4MaskScalar result(And(
    Soa4MaskScalarFromBools(true, true, false, false),
    Soa4MaskScalarFromBools(true, false, true, false)
));
Soa4MaskScalar ref = Soa4MaskScalarFromBools(true, false, false, false);

Validate( IsEqual(result, ref) );



SetFunctionName("Or(Soa4MaskScalar)");

Soa4MaskScalar result(Or(
    Soa4MaskScalarFromBools(true, true, false, false),
    Soa4MaskScalarFromBools(true, false, true, false)
));
Soa4MaskScalar ref(Soa4MaskScalarFromBools(true, true, true, false));

Validate( IsEqual(result, ref) );



SetFunctionName("Xor(Soa4MaskScalar)");

Soa4MaskScalar result(Xor(
    Soa4MaskScalarFromBools(true, true, false, false),
    Soa4MaskScalarFromBools(true, false, true, false)
));
Soa4MaskScalar ref(Soa4MaskScalarFromBools(false, true, true, false));

Validate( IsEqual(result, ref) );



SetFunctionName("CompEqual(Soa4MaskScalar)");

Soa4MaskScalar result(CompEqual(
    Soa4MaskScalarFromBools(true, true, false, false),
    Soa4MaskScalarFromBools(true, false, true, false)
));
Soa4MaskScalar ref(Soa4MaskScalarFromBools(true, false, false, true));

Validate( IsEqual(result, ref) );



SetFunctionName("CompNotEqual(Soa4MaskScalar)");

Soa4MaskScalar result(CompNotEqual(
    Soa4MaskScalarFromBools(true, true, false, false),
    Soa4MaskScalarFromBools(true, false, true, false)
));
Soa4MaskScalar ref(Soa4MaskScalarFromBools(false, true, true, false));

Validate( IsEqual(result, ref) );
